<?php namespace App\Http\Controllers\Inventory;
use App\Http\Controllers\Controller; use App\Models\{Product,Category,Brand,Unit,Warehouse,WarehouseStock,StockMovement}; use Illuminate\Http\Request;
class InventoryController extends Controller { public function index(Request $r){$warehouses=Warehouse::where('is_active',true)->orderBy('name')->get();$q=WarehouseStock::with(['product.category','warehouse']); if($r->filled('warehouse_id'))$q->where('warehouse_id',$r->integer('warehouse_id')); if($r->filled('search')){$s=$r->string('search');$q->whereHas('product',fn($p)=>$p->where('name','like',"%$s%")->orWhere('sku','like',"%$s%"));}$stocks=$q->latest()->paginate(15)->withQueryString();return view('inventory.index',compact('stocks','warehouses'));} public function movements(Request $r){$movements=StockMovement::with(['product','warehouse','user'])->latest()->paginate(20);return view('inventory.movements',compact('movements'));}}
